const MODES = ['uppercase', 'lowercase', 'slug'];
const ALLOWED_ARGS = new Set(['text', 'mode', 'trim']);

function slugify(text, trim) {
  let t = text.toLowerCase();
  if (trim) t = t.trim();
  // Replace runs of non-alphanumeric characters with a single hyphen,
  // then strip any leading/trailing hyphens.
  return t.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
}

export async function listTools() {
  return [
    {
      name: 'text_transform',
      description: 'Transform text to uppercase, lowercase, or slug form.',
      inputSchema: {
        type: 'object',
        properties: {
          text: { type: 'string', description: 'The text to transform.' },
          mode: {
            type: 'string',
            enum: MODES,
            description: 'Transform mode: uppercase, lowercase, or slug.'
          },
          trim: {
            type: 'boolean',
            default: true,
            description: 'Trim leading/trailing whitespace before transforming (defaults to true).'
          }
        },
        required: ['text', 'mode'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args = {}) {
  if (name !== 'text_transform') {
    throw new Error(`Unknown tool: ${name}`);
  }

  for (const key of Object.keys(args)) {
    if (!ALLOWED_ARGS.has(key)) {
      throw new Error(`Unexpected argument: ${key}`);
    }
  }

  const { text, mode, trim = true } = args;

  if (typeof text !== 'string') {
    throw new Error('Argument "text" is required and must be a string');
  }
  if (typeof mode !== 'string' || !MODES.includes(mode)) {
    throw new Error('Argument "mode" is required and must be one of: uppercase, lowercase, slug');
  }
  if (trim !== undefined && typeof trim !== 'boolean') {
    throw new Error('Argument "trim" must be a boolean');
  }

  let result;
  if (mode === 'slug') {
    result = slugify(text, trim);
  } else {
    let t = text;
    if (trim) t = t.trim();
    result = mode === 'uppercase' ? t.toUpperCase() : t.toLowerCase();
  }

  return { content: [{ type: 'text', text: result }] };
}

